/**
 * Korpus benchmark pemahaman bahasa lokal (mode offline).
 *
 * Tiap butir: pertanyaan dokter (sebagaimana diketik pemain, termasuk singkatan, bahasa gaul,
 * salah ketik, dan kata berimbuhan) + maksud yang diharapkan.
 * Format maksud: `T:<topik>` · `S:<gejala>` · `D:<gejala>/<topik>` · `R:<tinjauan>` ·
 * `greeting` · `thanks` · `consent` · `repeat`. Daftar kosong = memang tidak bisa dipahami.
 * Urutan maksud tidak dinilai.
 */
export interface NluCase {
  q: string;
  expect: string[];
}

const T = (id: string) => `T:${id}`;
const S = (id: string) => `S:${id}`;
const R = (id: string) => `R:${id}`;

